show databases;
use customer_behaviour;
show tables;
select count(*) from customer_analysis;
select * from customer_analysis limit 10;

-- Q1. what is the total revenue generated by male amd female ?

select gender, sum(purchase_amount) as revenue from customer_analysis group by gender;

-- Q2. which customers used a discounts but still spent more than the average purchase amount ?

select customer_id, purchase_amount from customer_analysis where discount_applied = 'Yes' and 
purchase_amount > (select avg(purchase_amount) from customer_analysis);

-- Q3. which are the top 5 products with highest average review ratings ?

select item_purchased, round(avg(review_rating),2) as average_rat from customer_analysis group by item_purchased order by average_rat desc limit 5;

-- Q4. compare the average purchase amount between standard and express shipping ?

select shipping_type, round(avg(purchase_amount),2) as average from customer_analysis where shipping_type in ('Express','Standard') group by shipping_type;

-- Q5. do subscribe spent more ? compare average spends and total revenue between subscriber and non-subscrier ?

select subscription_status, count(customer_id) as total_number, round(avg(purchase_amount),2) as average_spend,
sum(purchase_amount) as total_revenue from customer_analysis group by subscription_status;

-- Q6. which 5 products have the highest percentage of purchase with discounts applied ?

select item_purchased,
round(sum(case 
	when discount_applied ='Yes' then 1
    else 0
end) *100/count(*),2) as discount_percentage
from customer_analysis group by item_purchased order by discount_percentage desc limit 5;

-- Q7. segment customer into new, returning and loyal based on their total number of previous purchase and show the count of each segment ?

with cte1 as (select customer_id, previous_purchases,
case
	when previous_purchases = 1 then 'New'
    when previous_purchases between 2 and 15 then 'Returning'
    else 'Loyal'
end as customer_segment
from customer_analysis)
select customer_segment, count(*) as number_ from cte1 group by customer_segment;

-- Q8. what are the top 3 most purchased products within each category ?

select * from (select category, item_purchased,
count(customer_id) as total_number, row_number() over(partition by category order by count(customer_id) desc )
 as rnk from customer_analysis group by category, item_purchased) 
as my_dt where rnk <=3;

-- Q9. are customers who are repeat buyers (more than 5 previous purchase) are likely to subscribe ?
 
select subscription_status, count(customer_id) from customer_analysis where previous_purchases >5
group by subscription_status;

-- Q10. what is the revenue contribution of each age group ?

select age_category, sum(purchase_amount) as total_revenue from customer_analysis group by age_category order by total_revenue desc
